// Valida la entrada del subworkflow. Todo lo que llega aquí termina dentro de un prompt (OWASP A03): se acota y se delimita después
const THEMES = ["Libros", "Vinilos", "Teatro", "Fiestas", "Conciertos", "Conversatorios", "Proyecciones", "Presentaciones", "Café", "Comida", "Licores"];
const input = $input.first().json;
const contentItemId = String(input.content_item_id ?? '').trim().toLowerCase();
if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/.test(contentItemId)) {
  throw new Error('validation: content_item_id no es un UUID');
}

const ex = input.extraction;
const isNullableString = (v) => v === null || typeof v === 'string';
if (!ex || typeof ex !== 'object' || Array.isArray(ex)) throw new Error('validation: extraction debe ser un objeto');
if (!THEMES.includes(ex.tema)) throw new Error('validation: extraction.tema no es un tema de Le Tiende');
if (!isNullableString(ex.titulo) || !isNullableString(ex.autor_o_artista) || typeof ex.descripcion !== 'string'
  || !Array.isArray(ex.texto_visible) || !ex.texto_visible.every((t) => typeof t === 'string')) {
  throw new Error('validation: extraction no cumple el esquema de WF10');
}
// Se reconstruye con las claves conocidas: nada más entra al prompt
const extraction = {
  tema: ex.tema, titulo: ex.titulo, autor_o_artista: ex.autor_o_artista,
  texto_visible: ex.texto_visible.slice(0, 60), descripcion: ex.descripcion,
};
if (JSON.stringify(extraction).length > 20000) throw new Error('validation: extraction demasiado larga');

const notes = String(input.notes ?? '').trim();
if (notes.length > 2000) throw new Error('validation: notes supera 2000 caracteres');
// Correcciones de un reintento (las arma WF12); opcional
const feedback = String(input.feedback ?? '').trim();
if (feedback.length > 2000) throw new Error('validation: feedback supera 2000 caracteres');

return [{ json: { content_item_id: contentItemId, extraction, notes, feedback, started_at: new Date().toISOString() } }];

// Abre la fila del paso en pipeline_steps ('started'); el intento es el último + 1
const { content_item_id, extraction, notes, feedback, started_at } = $input.first().json;
const base = `${$env.SUPABASE_URL}/rest/v1/pipeline_steps`;
const key = $env.SUPABASE_SERVICE_ROLE_KEY;
const headers = { apikey: key, Authorization: `Bearer ${key}`, 'Content-Type': 'application/json' };

const previous = await this.helpers.httpRequest({
  method: 'GET', url: base, headers, json: true,
  qs: { content_item_id: `eq.${content_item_id}`, step: 'eq.write_captions', select: 'attempt', order: 'attempt.desc', limit: 1 },
});
const attempt = (previous?.[0]?.attempt ?? 0) + 1;

const created = await this.helpers.httpRequest({
  method: 'POST', url: base, json: true,
  headers: { ...headers, Prefer: 'return=representation' },
  body: { content_item_id, step: 'write_captions', attempt, status: 'started', started_at, n8n_execution_id: String($execution.id) },
});
const row = Array.isArray(created) ? created[0] : created;
if (!row?.id) throw new Error('supabase: pipeline_steps no devolvió el id de la fila');

return [{ json: { content_item_id, extraction, notes, feedback, started_at, step_id: row.id, attempt } }];

// Redacción de captions estructurada con la API Interactions (mismo esquema y prompt que scripts/eval-gemini.mjs)
const strArr = { type: 'array', items: { type: 'string' } };
const SCHEMA = {
  type: 'object',
  properties: {
    caption_instagram: { type: 'string' }, hashtags_instagram: strArr, caption_tiktok: { type: 'string' },
    hashtags_tiktok: strArr, title_youtube: { type: 'string' }, caption_youtube: { type: 'string' },
    tags_youtube: strArr, suggested_time_note: { type: 'string' },
  },
  required: ['caption_instagram', 'hashtags_instagram', 'caption_tiktok', 'hashtags_tiktok', 'title_youtube', 'caption_youtube', 'tags_youtube', 'suggested_time_note'],
  additionalProperties: false,
};

const { content_item_id, step_id, system, user } = $input.first().json;
const buildBody = (model) => ({
  model, system_instruction: system, store: false,
  input: [{ type: 'text', text: user }],
  response_format: { type: 'text', mime_type: 'application/json', schema: SCHEMA },
  generation_config: { thinking_level: 'low', max_output_tokens: 8192 },
});

// Modelo principal y alterno (T-0025): ante 429/500/503 persistentes se prueba el alterno, que tiene cuota propia
const MODELS = ['gemini-3.5-flash-lite', 'gemini-3.1-flash-lite'];

// Hasta 3 reintentos por modelo con backoff 1 s, 2 s, 4 s; solo ante 429/500/503 o fallo de red
const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
let response = null;
let lastError = '';
let attempts = 0;
let usedModel = MODELS[0];
let onlyQuota = true;
const t0 = Date.now();
outer: for (const model of MODELS) {
  usedModel = model;
  for (let retry = 0; retry <= 3; retry++) {
    if (retry > 0) await sleep(2 ** (retry - 1) * 1000);
    attempts++;
    try {
      response = await this.helpers.httpRequest({
        method: 'POST', url: 'https://generativelanguage.googleapis.com/v1beta/interactions',
        headers: { 'x-goog-api-key': $env.GEMINI_API_KEY, 'Content-Type': 'application/json' },
        body: buildBody(model), json: true, timeout: 120000, returnFullResponse: true, ignoreHttpStatusErrors: true,
      });
    } catch (e) {
      response = null;
      onlyQuota = false;
      lastError = `red (${model}): ${e.message}`;
      continue;
    }
    if (response.statusCode >= 200 && response.statusCode < 300) break outer;
    if (response.statusCode !== 429) onlyQuota = false;
    lastError = `HTTP ${response.statusCode} (${model}): ${String(response.body?.error?.message ?? '').slice(0, 300)}`;
    if (![429, 500, 503].includes(response.statusCode)) break outer; // 400/401/403/404: ni reintentar ni cambiar de modelo sirve
  }
}
const latency_ms = Date.now() - t0;

if (!response || response.statusCode < 200 || response.statusCode >= 300) {
  // 429 en todos los modelos: cuota del nivel gratuito agotada hasta el reinicio diario (ADR-013)
  if (response?.statusCode === 429 && onlyQuota) throw new Error(`waiting_quota: ${MODELS.join(' y ')} sin cuota tras ${attempts} intentos`);
  if (response?.statusCode === 401 || response?.statusCode === 403) throw new Error(`gemini_auth: ${lastError}`);
  throw new Error(`gemini_http: ${lastError} (${attempts} intentos)`);
}

const data = response.body ?? {};
const text = (data.steps ?? [])
  .filter((s) => s.type === 'model_output').flatMap((s) => s.content ?? [])
  .filter((c) => c.type === 'text').map((c) => c.text).join('');
let captions;
try { captions = JSON.parse(text); } catch (e) { throw new Error(`gemini_output: la respuesta no es JSON (${e.message})`); }

// El esquema ya lo exige la API; se revisa de nuevo porque los validadores (WF12) y la revisión dependen de estos campos
const isStrArr = (v) => Array.isArray(v) && v.every((x) => typeof x === 'string');
const okShape = ['caption_instagram', 'caption_tiktok', 'title_youtube', 'caption_youtube', 'suggested_time_note'].every((k) => typeof captions?.[k] === 'string')
  && ['hashtags_instagram', 'hashtags_tiktok', 'tags_youtube'].every((k) => isStrArr(captions?.[k]));
if (!okShape) throw new Error('gemini_output: los captions no cumplen el esquema');

const usage = data.usage ?? {};
const tokens_input = usage.total_input_tokens ?? null;
const tokens_output = usage.total_output_tokens ?? null;
return [{ json: {
  content_item_id, step_id, model: usedModel, fallback_used: usedModel !== MODELS[0], captions, latency_ms, attempts,
  usage: { input: tokens_input, output: tokens_output, thought: usage.total_thought_tokens ?? null },
  // Nivel gratuito sin facturación (ADR-013): costo 0
  step_patch: { status: 'succeeded', finished_at: new Date().toISOString(), model: usedModel, tokens_input, tokens_output, cost_usd: 0 },
} }];

// Normaliza el fallo de cualquier nodo para pipeline_steps, error_log y Telegram
const raw = $input.first().json;
const message = String(raw.error?.message ?? raw.error ?? raw.message ?? 'Error sin mensaje')
  // Nunca registrar el token del bot que va en las URLs de archivos de Telegram
  .replace(/bot\d+:[A-Za-z0-9_-]+/g, 'bot***')
  .slice(0, 2000);
const prefix = (message.match(/^([a-z_]+):/) ?? [])[1];
// Sin prefijo propio (p. ej. un 404 del nodo HTTP), la etapa es el último nodo que llegó a ejecutarse
const stages = [['Registrar inicio', 'supabase'], ['Preparar petición', 'prompt'],
  ['Llamar a Gemini', 'gemini'], ['Cerrar paso exitoso', 'supabase']];
const stage = stages.filter(([node]) => $(node).isExecuted).pop()?.[1];
const error_type = prefix ?? stage ?? 'execution_error';

// Desde una rama de error, first() sin argumentos lee la salida 1 (error) del nodo: hay que pedir la salida 0
const input = $('Entrada').first(0, 0)?.json ?? {};
// Si 'Registrar inicio' no corrió o falló, no hay fila abierta en pipeline_steps
const step = $('Registrar inicio').isExecuted ? ($('Registrar inicio').first(0, 0)?.json ?? null) : null;
const contentItemId = /^[0-9a-f-]{36}$/i.test(String(input.content_item_id ?? '')) ? String(input.content_item_id).toLowerCase() : null;
const status = error_type === 'waiting_quota' ? 'waiting_quota' : 'failed';

return [{ json: {
  has_step: Boolean(step?.step_id),
  step_id: step?.step_id ?? null,
  step_patch: { status, finished_at: new Date().toISOString(), error_type, error_message: message },
  error_log_row: {
    workflow: '11-redactar-captions', content_item_id: contentItemId, error_type, error_message: message,
    stack_trace: JSON.stringify({ execution_id: $execution.id, error: raw.error ?? raw }).replace(/bot\d+:[A-Za-z0-9_-]+/g, 'bot***').slice(0, 8000),
  },
  telegram_text: `⚠️ 11 - Redactar captions (${error_type})\nItem: ${contentItemId ?? 'sin id válido'}\nEjecución: ${$execution.id}\n\n${message.slice(0, 500)}`,
  result: { ok: false, content_item_id: contentItemId, status, error_type, error_message: message },
} }];
